* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: #090d16;
  color: #f1f5f9;
  padding: 40px 20px;
}

.dashboard-wrapper {
  max-width: 1200px;
  margin: 0 auto;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 32px;
}

.pill {
  background: rgba(16, 185, 129, 0.1);
  color: #10b981;
  border: 1px solid rgba(16, 185, 129, 0.2);
  padding: 4px 10px;
  border-radius: 99px;
  font-size: 0.75rem;
  font-weight: 700;
}

h1 {
  margin: 8px 0 4px 0;
  font-size: 2.2rem;
  letter-spacing: -0.03em;
}

.subtitle {
  margin: 0;
  color: #94a3b8;
  font-size: 0.95rem;
}

.action-btn {
  background: #3b82f6;
  color: white;
  border: 0;
  padding: 10px 20px;
  border-radius: 10px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.2s;
}

.action-btn:hover {
  opacity: 0.9;
}

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-bottom: 32px;
}

.kpi-card {
  background: #111827;
  border: 1px solid #1f2937;
  padding: 24px;
  border-radius: 16px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.3);
}

.kpi-card .label {
  color: #94a3b8;
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
}

.kpi-card .value {
  font-size: 2.1rem;
  font-weight: 800;
  margin: 8px 0;
  letter-spacing: -0.02em;
}

.trend {
  font-size: 0.8rem;
  font-weight: 600;
}

.trend.positive {
  color: #10b981;
}

.trend.negative {
  color: #f43f5e;
}

.main-grid {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 24px;
}

.card {
  background: #111827;
  border: 1px solid #1f2937;
  padding: 28px;
  border-radius: 20px;
}

.card h2 {
  margin: 0 0 4px 0;
  font-size: 1.35rem;
  letter-spacing: -0.02em;
}

.card-sub {
  margin: 0 0 24px 0;
  color: #64748b;
  font-size: 0.85rem;
}

.progress-stack {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.progress-labels {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
  margin-bottom: 8px;
}

.progress-bar {
  background: #1f2937;
  height: 10px;
  border-radius: 99px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  border-radius: 99px;
}

.progress-fill.blue {
  background: #3b82f6;
}

.progress-fill.amber {
  background: #f59e0b;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th {
  color: #64748b;
  font-size: 0.75rem;
  text-transform: uppercase;
  padding: 12px 16px;
  border-bottom: 1px solid #1f2937;
  text-align: left;
}

td {
  padding: 16px;
  font-size: 0.9rem;
  border-bottom: 1px solid #1f2937;
}

.bold {
  font-weight: 600;
}

.expense {
  color: #f43f5e;
  font-weight: 600;
}

.income {
  color: #10b981;
  font-weight: 600;
}

.status-badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 99px;
  font-size: 0.75rem;
  font-weight: 700;
}

.status-badge.green {
  background: rgba(16, 185, 129, 0.1);
  color: #10b981;
}

.status-badge.yellow {
  background: rgba(245, 158, 11, 0.1);
  color: #f59e0b;
}

@media (max-width: 900px) {
  .kpi-grid,
  .main-grid {
    grid-template-columns: 1fr;
  }
}
